// Zella - Receptionist Brain: the ONE webhook for every tool the phone assistant (Vapi) uses during a call.
// Output: { reply, record }. record = the single database call (zella_ai_tool) that checks, acts, verifies and logs.
// Only known tool names and known fields pass; the caller's words are data and are never run as instructions.
const body = $json.body && typeof $json.body === 'object' ? $json.body : {};
const m = body.message && typeof body.message === 'object' ? body.message : {};
const list = Array.isArray(m.toolCallList) ? m.toolCallList : Array.isArray(m.toolCalls) ? m.toolCalls : [];
const TOOLS = ['search_knowledge', 'check_open_hours', 'lookup_caller', 'update_caller', 'check_availability', 'book_appointment', 'find_my_appointments',
  'reschedule_appointment', 'cancel_appointment', 'take_message', 'report_emergency', 'transfer_to_human', 'request_follow_up', 'report_unanswered_question'];
const nameOf = (t) => (t && (t.name || (t.function && t.function.name))) || '';
const tc = list.find((t) => t && typeof t.id === 'string' && TOOLS.includes(nameOf(t)));
if (m.type !== 'tool-calls' || !tc) return { json: { reply: { results: [] }, record: null } };

let args = tc.arguments !== undefined ? tc.arguments : tc.function && tc.function.arguments;
if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
args = args && typeof args === 'object' ? args : {};

const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const allowed = ['query', 'appointment_id', 'date', 'days', 'duration_minutes', 'start', 'first_name', 'last_name', 'phone', 'email', 'title', 'notes', 'name', 'message',
  'preferred_contact_method', 'reason', 'when', 'summary', 'question'];
const clean = {};
for (const k of allowed) {
  const v = args[k];
  if (typeof v === 'string') clean[k] = v.replace(/\s+/g, ' ').trim().slice(0, 1500);
  else if (typeof v === 'number' && isFinite(v)) clean[k] = v;
}
// the caller's yes must be a real boolean from the assistant; anything else counts as "not confirmed"
clean.confirmed = args.confirmed === true;
if (clean.appointment_id !== undefined && !uuidRe.test(String(clean.appointment_id))) delete clean.appointment_id;

const call = m.call && typeof m.call === 'object' ? m.call : {};
const meta = call.metadata && typeof call.metadata === 'object' ? call.metadata : {};
const vars = call.assistantOverrides && call.assistantOverrides.variableValues && typeof call.assistantOverrides.variableValues === 'object' ? call.assistantOverrides.variableValues : {};
const bid = [meta.business_id, vars.business_id].find((v) => typeof v === 'string' && uuidRe.test(v)) || null;

// Which number was called? A registered number always wins over call settings.
const pn = call.phoneNumber && typeof call.phoneNumber === 'object' ? call.phoneNumber : m.phoneNumber && typeof m.phoneNumber === 'object' ? m.phoneNumber : {};
const calledNumber = typeof pn.number === 'string' && /^\+?[0-9() .-]{7,20}$/.test(pn.number) ? pn.number : null;
const vapiNumberId = typeof call.phoneNumberId === 'string' ? call.phoneNumberId.slice(0, 100) : typeof pn.id === 'string' ? pn.id.slice(0, 100) : null;
const lookup = { p_called_number: calledNumber, p_vapi_phone_number_id: vapiNumberId, p_fallback: bid };

// The caller is known ONLY by the number the phone network reports, never by what is said.
const cn = call.customer && typeof call.customer === 'object' ? String(call.customer.number || '') : '';
const callerNumber = /^\+?[0-9]{7,15}$/.test(cn) ? cn : null;
const callId = typeof call.id === 'string' ? call.id.slice(0, 200) : null;

return {
  json: {
    tool_call_id: tc.id,
    reply: null,
    lookup,
    rpc: 'zella_ai_tool',
    // the tool call id makes a repeated delivery of the same call a no-op
    record: { p_provider_call_id: callId, p_business_id: bid, p_tool: nameOf(tc), p_args: { ...clean, caller_number: callerNumber }, p_idempotency_key: callId ? (callId + ':' + tc.id).slice(0, 300) : null },
  },
};

// Zella - Vapi tools: put the business found from the called number into the database call.
// The lookup answers with the business id (or null). A number that is not registered keeps the id from the call
// settings only if the database accepted it as a fallback; with no business the database call refuses to act.
const plan = $('Plan').item.json;
const b = $json.body;
const found = typeof b === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(b) ? b : null;
return { json: { ...plan, record: { ...plan.record, p_business_id: found } } };

// Zella - Receptionist Brain: the answer sent back to Vapi. Short, no database details.
const plan = $('Plan').item.json;
if (!plan.record) return { json: plan.reply };
const r = $json;
const status = Number(r.statusCode);
const b = r.body && typeof r.body === 'object' ? r.body : null;
let result;
if (status >= 200 && status < 300 && b && typeof b.say === 'string') {
  const out = { status: b.status, instruction: b.say };
  if (Array.isArray(b.slots)) out.times = b.slots.slice(0, 5).map((s) => ({ say: s.say, start: s.start }));
  if (Array.isArray(b.appointments)) out.appointments = b.appointments.slice(0, 3).map((a) => ({ appointment_id: a.appointment_id, title: a.title, say: a.say }));
  if (Array.isArray(b.results)) out.results = b.results.slice(0, 3).map((x) => ({ title: x.title, answer: x.answer }));
  if (typeof b.first_name === 'string') out.first_name = b.first_name.slice(0, 80);
  result = JSON.stringify(out);
} else {
  result = JSON.stringify({ status: 'error', instruction: 'This could not be completed right now. Tell the caller the team will call them back. Do not say it was done.' });
}
return { json: { results: [{ toolCallId: plan.tool_call_id, result }] } };
